[CmdletBinding()]
param()
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

# Encoded PE/PDB/listing controls only. Generated bytes never execute.
$repo = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
if (-not ('RedPrismBuild.IsaScanner' -as [type])) {
    Add-Type -Path (Join-Path $repo 'Build/IsaScan.cs')
}
$script:ImageBase = [UInt64]0x140000000
$script:SectionRva = [UInt32]0x002a0000
$script:ProcBegin = [UInt32]0x002aef90
$script:Dispatch = [UInt32]0x002afba9
$script:Table = [UInt32]0x002b13b8
$script:ProcEnd = [UInt32]0x002b13d0
# Each little-endian RVA is itself a four-byte VEX-prefixed listing row in the six-entry table.
# Those RVAs name six ordinary NOP instruction boundaries in the synthetic procedure body.
$script:Targets = [UInt32[]]@(0x002afbc5,0x002afcc5,0x002afdc5,0x002afec5,0x002affc5,0x002b00c5)
$script:RbxProducerRva = [UInt32]0x002afb80
$script:Guid = [guid]'b1d1f4a7-cb31-4c2a-91f7-6a0d8d672540'
$script:Age = [UInt32]11
$script:Rows = @(
    @{Name='Cmp'; Rva=0x002afba9; Bytes=[byte[]]@(0x83,0xfb,0x05); Text='cmp ebx, 5'},
    @{Name='Ja'; Rva=0x002afbac; Bytes=[byte[]]@(0x0f,0x87,0,0,0,0); Text='ja default'},
    @{Name='Lea'; Rva=0x002afbb2; Bytes=[byte[]]@(0x48,0x8d,0x15,0,0,0,0); Text='lea rdx, [rip+imagebase]'},
    @{Name='Load'; Rva=0x002afbb9; Bytes=[byte[]]@(0x8b,0x8c,0x9a,0,0,0,0); Text='mov ecx, dword ptr [rdx+rbx*4+table]'},
    @{Name='Add'; Rva=0x002afbc0; Bytes=[byte[]]@(0x48,0x03,0xca); Text='add rcx, rdx'},
    @{Name='Jmp'; Rva=0x002afbc3; Bytes=[byte[]]@(0xff,0xe1); Text='jmp rcx'}
)
function Set-U16([byte[]]$b,[int]$o,[UInt16]$v) { [Array]::Copy([BitConverter]::GetBytes($v),0,$b,$o,2) }
function Set-U32([byte[]]$b,[int]$o,[UInt32]$v) { [Array]::Copy([BitConverter]::GetBytes($v),0,$b,$o,4) }
function Set-U64([byte[]]$b,[int]$o,[UInt64]$v) { [Array]::Copy([BitConverter]::GetBytes($v),0,$b,$o,8) }
function Put([byte[]]$b,[int]$o,[byte[]]$v) { [Array]::Copy($v,0,$b,$o,$v.Length) }
function Hex([byte[]]$b) { ($b | ForEach-Object { $_.ToString('x2') }) -join ' ' }
function Raw([UInt32]$r) { [int](0x400 + $r - $script:SectionRva) }
function Add-ListingRow([Collections.Generic.List[string]]$rows,[UInt32]$r,[byte[]]$b,[string]$text) {
    $rows.Add(('{0:x}: {1} {2}' -f ($script:ImageBase+$r),(Hex $b),$text))
}
function Remove-ListingRange([Collections.Generic.List[string]]$rows,[UInt32]$start,[int]$length) {
    for($n=0;$n -lt $length;$n++){$prefix='{0:x}:' -f ($script:ImageBase+$start+[UInt32]$n);[void]$rows.RemoveAll([Predicate[string]]{param($line) $line.StartsWith($prefix)})}
}
function New-Control([string]$Name,[string]$Fault,[int]$FaultRow=-1) {
    $dir=Join-Path $script:FixtureRoot $Name
    [void](New-Item -ItemType Directory -Path $dir -Force)
    [byte[]]$pe=[byte[]]::new(0x30400)
    $pe[0]=0x4d; $pe[1]=0x5a; Set-U32 $pe 0x3c 0x80; Set-U32 $pe 0x80 0x4550
    Set-U16 $pe 0x84 0x8664; Set-U16 $pe 0x86 1; Set-U16 $pe 0x94 0xf0; Set-U16 $pe 0x98 0x20b
    Set-U64 $pe (0x98+24) $script:ImageBase; Set-U32 $pe (0x98+56) 0x30000; Set-U32 $pe (0x98+60) 0x400
    Set-U32 $pe (0x98+112+48) 0x002a0180; Set-U32 $pe (0x98+116+48) 28
    $sh=0x80+24+0xf0; Put $pe $sh ([Text.Encoding]::ASCII.GetBytes('.text'+[char]0+[char]0+[char]0))
    Set-U32 $pe ($sh+8) 0x30000; Set-U32 $pe ($sh+12) $script:SectionRva; Set-U32 $pe ($sh+16) 0x30000; Set-U32 $pe ($sh+20) 0x400; Set-U32 $pe ($sh+36) 0x60000020
    Set-U32 $pe (0x400+0x180+12) 2; Set-U32 $pe (0x400+0x180+16) 24; Set-U32 $pe (0x400+0x180+20) 0x002a01a0; Set-U32 $pe (0x400+0x180+24) 0x5a0
    Put $pe 0x5a0 ([Text.Encoding]::ASCII.GetBytes('RSDS')); Put $pe 0x5a4 $script:Guid.ToByteArray(); Set-U32 $pe 0x5b4 $script:Age
    # Complete one-byte instruction map for the procedure body, then replace exact rows below.
    for($r=$script:ProcBegin;$r -lt $script:ProcEnd;$r++){$pe[(Raw $r)]=0x90}
    $rows=[Collections.Generic.List[string]]::new()
    [byte[]]$producer=@(0x48,0x63,0x5d,0xa0);$producerText='movsxd rbx, dword ptr [rbp-0x60]'
    if($Fault -eq 'ProducerMissing'){$producer=@(0x90,0x90);$producerText='nop'}
    if($Fault -eq 'ProducerAlternateDisp8'){$producer=@(0x48,0x63,0x5d,0xa8);$producerText='movsxd rbx, dword ptr [rbp-0x58]'}
    if($Fault -eq 'ProducerWrongDestination'){$producer=@(0x48,0x63,0x55,0xa0);$producerText='movsxd rdx, dword ptr [rbp-0x60]'}
    if($Fault -in @('Producer64BitWrite','ProducerUnknown')){$producer=@(0x48,0x89,0xdb);$producerText=if($Fault -eq 'ProducerUnknown'){'<unknown>'}else{'mov rbx, rbx'}}
    Put $pe (Raw $script:RbxProducerRva) $producer
    if($Fault -ne 'ProducerMissing'){
        if($Fault -eq 'ProducerListing'){$reportedProducer=[byte[]]$producer.Clone();$reportedProducer[$reportedProducer.Length-1]=$reportedProducer[$reportedProducer.Length-1]-bxor 1}else{$reportedProducer=$producer}
        Add-ListingRow $rows $script:RbxProducerRva $reportedProducer $producerText
        if($Fault -eq 'ProducerDuplicate'){Add-ListingRow $rows $script:RbxProducerRva $reportedProducer $producerText}
    }
    [byte[]]$effectBytes=@();$effectText=''
    switch($Fault){
        'EffectMovRbxImm64' {$effectBytes=@(0x48,0xbb,0,0,0,0,0,0,0,0x80);$effectText='mov rbx, 0x8000000000000000'}
        'EffectMovRbxRax' {$effectBytes=@(0x48,0x89,0xc3);$effectText='mov rbx, rax'}
        'EffectLeaRbx' {$effectBytes=@(0x48,0x8d,0x18);$effectText='lea rbx, [rax]'}
        'EffectAddRbx' {$effectBytes=@(0x48,0x83,0xc3,0x01);$effectText='add rbx, 1'}
        'EffectPopRbx' {$effectBytes=@(0x5b);$effectText='pop rbx'}
        'EffectXchgRbx' {$effectBytes=@(0x48,0x93);$effectText='xchg rbx, rax'}
        'EffectMovCrToRbx' {$effectBytes=@(0x0f,0x20,0xdb);$effectText='mov rbx, cr3'}
        'EffectXop8F' {$effectBytes=@(0x8f,0xe8,0x78,0xc0,0xc1);$effectText='vprotb xmm0, xmm0, xmm1'}
        'EffectC7Group1' {$effectBytes=@(0x48,0xc7,0xc8,0x01,0,0,0);$effectText='unmodelled C7 group 1 immediate'}
        'EffectVirtualMonitorCall' {$effectBytes=@(0x0f,0x01,0xc1);$effectText='vmcall'}
        'EffectInterrupt' {$effectBytes=@(0xcd,0x2e);$effectText='int 0x2e'}
        'EffectMovEbxEax' {$effectBytes=@(0x89,0xc3);$effectText='mov ebx, eax'}
        'EffectMovEaxEbx' {$effectBytes=@(0x89,0xd8);$effectText='mov eax, ebx'}
        'EffectMovRdxRbx' {$effectBytes=@(0x48,0x89,0xda);$effectText='mov rdx, rbx'}
        'EffectPushRbx' {$effectBytes=@(0x53);$effectText='push rbx'}
        'EffectMovBl' {$effectBytes=@(0xb3,0x01);$effectText='mov bl, 1'}
        'EffectMovBx' {$effectBytes=@(0x66,0xbb,0x01,0x00);$effectText='mov bx, 1'}
        'ProducerSingle64Clobber' {$effectBytes=@(0x48,0x89,0xdb);$effectText='mov rbx, rbx'}
    }
    $indexStart=[UInt32]($script:Dispatch+3+6)
    for($i=0;$i -lt $script:Rows.Count;$i++){
        $spec=$script:Rows[$i]; [byte[]]$b=$spec.Bytes.Clone(); $text=$spec.Text
        if($spec.Name -eq 'Ja'){$target=switch($Fault){'DefaultTargetIsCase0' {[UInt32]$script:Targets[0]};'DefaultTargetIntoLoad' {[UInt32]$script:Rows[3].Rva};'JaTargetIntoLoad' {[UInt32]$script:Rows[3].Rva};'AlternateJaDefault' {[UInt32]0x002affc4};default {[UInt32]0x002affc5}}; [Array]::Copy([BitConverter]::GetBytes([Int32]([Int64]$target-[Int64]($spec.Rva+6))),0,$b,2,4)}
        if($spec.Name -eq 'Lea'){[Array]::Copy([BitConverter]::GetBytes([Int32](-[Int64]($spec.Rva+7))),0,$b,3,4)}
        if($spec.Name -eq 'Load'){Set-U32 $b 3 $script:Table}
        switch($Fault){
            'WrongCmpOpcode' {if($spec.Name -eq 'Cmp'){$b[0]=0x81}}
            'WrongCmpRegister' {if($spec.Name -eq 'Cmp'){$b[1]=0xf3}}
            'WrongCmpImmediate' {if($spec.Name -eq 'Cmp'){$b[2]=4}}
            'WrongCount' {if($spec.Name -eq 'Cmp'){$b[2]=4}}
            'Max0' {if($spec.Name -eq 'Cmp'){$b[2]=0}}
            'Max128' {if($spec.Name -eq 'Cmp'){$b[2]=0x80}}
            'WrongJaCondition' {if($spec.Name -eq 'Ja'){$b[1]=0x86}}
            'WrongLeaRegister' {if($spec.Name -eq 'Lea'){$b[2]=0x0d}}
            'WrongImageBase' {if($spec.Name -eq 'Lea'){$b[3]=$b[3]-bxor 1}}
            'WrongLoadOpcode' {if($spec.Name -eq 'Load'){$b[1]=0x89}}
            'WrongLoadDestination' {if($spec.Name -eq 'Load'){$b[1]=0x84}}
            'WrongLoadBase' {if($spec.Name -eq 'Load'){$b[2]=0x99}}
            'WrongLoadIndex' {if($spec.Name -eq 'Load'){$b[2]=0x92}}
            'WrongLoadScale' {if($spec.Name -eq 'Load'){$b[2]=0x8a}}
            'WrongTableOperand' {if($spec.Name -eq 'Load'){Set-U32 $b 3 ($script:Table+4)}}
            'WrongAddOpcode' {if($spec.Name -eq 'Add'){$b[1]=0x01}}
            'WrongAddRegisters' {if($spec.Name -eq 'Add'){$b[2]=0xc8}}
            'WrongJumpOpcode' {if($spec.Name -eq 'Jmp'){$b[0]=0x90;$b[1]=0x90}}
            'WrongJumpRegister' {if($spec.Name -eq 'Jmp'){$b[1]=0xe2}}
        }
        $mode=''
        if($FaultRow -eq $i -and $Fault -match '^(Missing|Duplicate|Unknown|Listing)Row$'){$mode=$Matches[1]}
        if($mode -eq 'Missing'){continue}
        if($mode -eq 'Unknown'){$text='<unknown>'}
        if($mode -eq 'Listing'){$reported=[byte[]]$b.Clone();$reported[$reported.Length-1]=$reported[$reported.Length-1]-bxor 1}else{$reported=$b}
        Put $pe (Raw $spec.Rva) $b
        Add-ListingRow $rows $spec.Rva $reported $text
        if($mode -eq 'Duplicate'){Add-ListingRow $rows $spec.Rva $reported $text}
    }
    # Explicit NOP body rows preserve decoded coverage except at dispatcher, terminal, table, and VEX target labels.
    $reserved=[Collections.Generic.HashSet[UInt32]]::new()
    foreach($s in $script:Rows){for($j=0;$j -lt $s.Bytes.Length;$j++){[void]$reserved.Add([UInt32]($s.Rva+$j))}}
    for($j=0;$j -lt $producer.Length;$j++){[void]$reserved.Add([UInt32]($script:RbxProducerRva+$j))}
    if($effectBytes.Length -gt 0){for($j=0;$j -lt $effectBytes.Length;$j++){[void]$reserved.Add([UInt32]($script:RbxProducerRva+8+$j))}}
    foreach($target in $script:Targets){[void]$reserved.Add([UInt32]$target)}
    if($Fault -in @('DirectBypassIndex','PreGuardEntryCmpFromLaterBody')){for($j=0;$j -lt 5;$j++){[void]$reserved.Add([UInt32](0x002afba0+$j))}}
    if($Fault -eq 'OtherIndirectJump'){for($j=0;$j -lt 2;$j++){[void]$reserved.Add([UInt32](0x002afe70+$j))}}
    for($r=$script:ProcBegin;$r -lt 0x002b13b2;$r++){
        if(-not $reserved.Contains($r)){[byte[]]$nop=@(0x90);Add-ListingRow $rows $r $nop 'nop'}
    }
    foreach($target in $script:Targets){[byte[]]$nop=@(0x90);Add-ListingRow $rows $target $nop 'nop'}
    if($Fault -eq 'TargetMidInstruction4'){
        $midStart=[UInt32]0x002affc5;[byte[]]$midBytes=@(0x48,0x89,0xc0);Remove-ListingRange $rows $midStart $midBytes.Length;Put $pe (Raw $midStart) $midBytes;Add-ListingRow $rows $midStart $midBytes 'mov rax, rax'
    }
    if($Fault -eq 'WrongTableTarget4'){Remove-ListingRange $rows 0x002b13b1 1}
    if($effectBytes.Length -gt 0){$at=[UInt32]($script:RbxProducerRva+8);Remove-ListingRange $rows $at $effectBytes.Length;Put $pe (Raw $at) $effectBytes;Add-ListingRow $rows $at $effectBytes $effectText}
    # The procedure-ending CALL and INT3 are fixed at the captured addresses. The clean call targets a known
    # RET row outside this procedure; the explicit LocalTerminalCall fault targets into this body.
    [byte[]]$call=@(0xe8,0,0,0,0); [byte[]]$trap=@(0xcc)
    $terminalCallTarget=[UInt32]($script:ProcBegin-0x20)
    if($Fault -eq 'LocalTerminalCall'){$terminalCallTarget=[UInt32]($script:ProcBegin+0x20)}
    [Array]::Copy([BitConverter]::GetBytes([Int32]([Int64]$terminalCallTarget-[Int64](0x002b13b7))),0,$call,1,4)
    if($Fault -eq 'MissingCall'){$call=@(0x90,0x90,0x90,0x90,0x90)}
    if($Fault -eq 'WrongCall'){$call=@(0xff,0xd0,0x90,0x90,0x90)}
    if($Fault -eq 'MissingTrap'){$trap=@(0x90)}
    if($Fault -eq 'WrongTrap'){$trap=@(0xc3)}
    Put $pe (Raw 0x002b13b2) $call;Put $pe (Raw 0x002b13b7) $trap
    Add-ListingRow $rows 0x002b13b2 $call $(if($call[0] -eq 0xe8){'call direct-target'}else{'nop'})
    Add-ListingRow $rows 0x002b13b7 $trap $(if($trap[0] -eq 0xcc){'int3'}elseif($trap[0] -eq 0xc3){'ret'}else{'nop'})
    if($Fault -ne 'LocalTerminalCall'){Put $pe (Raw ($script:ProcBegin-0x20)) ([byte[]]@(0xc3));Add-ListingRow $rows ([UInt32]($script:ProcBegin-0x20)) ([byte[]]@(0xc3)) 'ret external-call-target'}
    $tableRva=$script:Table
    if($Fault -eq 'TableAfterPadding'){$tableRva++;$pe[(Raw $script:Table)]=0x90;Add-ListingRow $rows $script:Table ([byte[]]@(0x90)) 'nop'}
    if($Fault -eq 'TableMidInstruction'){$tableRva--}
    $targetList=[UInt32[]]$script:Targets.Clone()
    if($Fault -eq 'TargetNonVex4'){$targetList[4]=0x002afcc3}
    if($Fault -eq 'TargetMidInstruction4'){$targetList[4]=0x002affc6}
    if($Fault -eq 'WrongTableTarget4'){$targetList[4]=0x002b13b1}
    for($i=0;$i -lt 6;$i++){
        $at=[UInt32]($tableRva+4*$i);Set-U32 $pe (Raw $at) $targetList[$i]
        [byte[]]$entry=$pe[(Raw $at)..(Raw ($at+3))]
        $text=if($entry[0] -eq 0xc5){'vex synthetic data row'}else{'add byte ptr [rax], al'}
        Add-ListingRow $rows $at $entry $text
    }
    if($Fault -eq 'RealBodyVex'){
        [byte[]]$v=@(0xc5,0xf8,0x10,0x00);Remove-ListingRange $rows 0x002afe80 $v.Length;Put $pe (Raw 0x002afe80) $v;Add-ListingRow $rows 0x002afe80 $v 'vmovups xmm0, xmmword ptr [rax]'
    }
    if($Fault -eq 'KnownIndirectCallAllowed'){
        $at=[UInt32]0x002afbe0;[byte[]]$callRow=@(0xff,0xd0);Remove-ListingRange $rows $at $callRow.Length
        Put $pe (Raw $at) $callRow;Add-ListingRow $rows $at $callRow 'call rax'
    }
    if($Fault -eq 'RealAdjacentEvex'){
        [byte[]]$v=@(0x62,0xf1,0x7c,0x08,0x10,0x00);Put $pe (Raw $script:ProcEnd) $v;Add-ListingRow $rows $script:ProcEnd $v 'vmovups xmm0, xmmword ptr [rax]'
    }
    if($Fault -eq 'LaterAnonymousAfterPadding'){
        for($j=0;$j -lt 16;$j++){$pe[(Raw ($script:ProcEnd+$j))]=0xcc;Add-ListingRow $rows ([UInt32]($script:ProcEnd+$j)) ([byte[]]@(0xcc)) 'int3'}
    }
    if($Fault -eq 'DirectBypassIndex' -or $Fault -eq 'PreGuardEntryCmpFromLaterBody'){
        $at=[UInt32]0x002afba0;$dest=if($Fault -eq 'DirectBypassIndex'){$indexStart}else{$script:Dispatch};[byte[]]$jmp=@(0xe9,0,0,0,0)
        [Array]::Copy([BitConverter]::GetBytes([Int32]([Int64]$dest-[Int64]($at+5))),0,$jmp,1,4);Remove-ListingRange $rows $at $jmp.Length;Put $pe (Raw $at) $jmp;Add-ListingRow $rows $at $jmp 'jmp direct-bypass'
    }
    if($Fault -eq 'OtherIndirectJump'){$at=[UInt32]0x002afe70;[byte[]]$jmp=@(0xff,0xe0);Remove-ListingRange $rows $at $jmp.Length;Put $pe (Raw $at) $jmp;Add-ListingRow $rows $at $jmp 'jmp rax'}
    if($Fault -eq 'EntryBypassesProducer'){
        $at=[UInt32]($script:ProcBegin+0x10);$dest=[UInt32]$script:Dispatch;[byte[]]$jmp=@(0xe9,0,0,0,0)
        [Array]::Copy([BitConverter]::GetBytes([Int32]([Int64]$dest-[Int64]($at+5))),0,$jmp,1,4);Remove-ListingRange $rows $at $jmp.Length;Put $pe (Raw $at) $jmp
        Add-ListingRow $rows $at $jmp 'jmp direct-entry-bypass-producer'
    }
    if($Fault -in @('EntryIntoProducer','EntryIntoJa','EntryIntoLea','EntryIntoLoad','EntryIntoAdd','EntryIntoJump')){
        $at=[UInt32]($script:ProcBegin+0x10)
        $dest=switch($Fault){'EntryIntoProducer'{$script:RbxProducerRva};'EntryIntoJa'{$script:Rows[1].Rva};'EntryIntoLea'{$script:Rows[2].Rva};'EntryIntoLoad'{$script:Rows[3].Rva};'EntryIntoAdd'{$script:Rows[4].Rva};'EntryIntoJump'{$script:Rows[5].Rva}}
        [byte[]]$jmp=@(0xe9,0,0,0,0);[Array]::Copy([BitConverter]::GetBytes([Int32]([Int64]$dest-[Int64]($at+5))),0,$jmp,1,4);Remove-ListingRange $rows $at $jmp.Length;Put $pe (Raw $at) $jmp
        Add-ListingRow $rows $at $jmp ('jmp direct-entry-' + $Fault)
    }
    if($Fault -eq 'LocalCallIntoGuard'){
        $at=[UInt32]($script:ProcBegin+0x10);$dest=[UInt32]$script:Dispatch;[byte[]]$localCall=@(0xe8,0,0,0,0)
        [Array]::Copy([BitConverter]::GetBytes([Int32]([Int64]$dest-[Int64]($at+5))),0,$localCall,1,4);Remove-ListingRange $rows $at $localCall.Length;Put $pe (Raw $at) $localCall
        Add-ListingRow $rows $at $localCall 'call local-guard'
    }
    if($Fault -eq 'ProducerCrossingEntry'){
        $at=[UInt32]($script:ProcBegin+0x10);$dest=[UInt32]($script:RbxProducerRva+1);[byte[]]$jmp=@(0xe9,0,0,0,0)
        [Array]::Copy([BitConverter]::GetBytes([Int32]([Int64]$dest-[Int64]($at+5))),0,$jmp,1,4);Remove-ListingRange $rows $at $jmp.Length;Put $pe (Raw $at) $jmp
        Add-ListingRow $rows $at $jmp 'jmp into producer instruction'
    }
    if($Fault -in @('PreGuardEntryCmp','PreGuardBypassJa','PreGuardBypassLea','PreGuardBypassLoad','PreGuardBypassAdd','PreGuardBypassJump')){
        $at=[UInt32]($script:RbxProducerRva+8)
        $dest=switch($Fault){'PreGuardEntryCmp'{$script:Dispatch};'PreGuardBypassJa'{$script:Rows[1].Rva};'PreGuardBypassLea'{$script:Rows[2].Rva};'PreGuardBypassLoad'{$script:Rows[3].Rva};'PreGuardBypassAdd'{$script:Rows[4].Rva};'PreGuardBypassJump'{$script:Rows[5].Rva}}
        [byte[]]$jmp=@(0xe9,0,0,0,0);[Array]::Copy([BitConverter]::GetBytes([Int32]([Int64]$dest-[Int64]($at+5))),0,$jmp,1,4);Remove-ListingRange $rows $at $jmp.Length;Put $pe (Raw $at) $jmp
        Add-ListingRow $rows $at $jmp ('jmp preguard-bypass-' + $Fault)
    }
    if($Fault -in @('BodyRowMissing','BodyRowDuplicate','BodyRowUnknown','BodyRowListing')){
        $at=[UInt32]($script:ProcBegin+2);$rows.RemoveAll([Predicate[string]]{param($line) $line.StartsWith(('{0:x}:' -f ($script:ImageBase+$at)))})
        [byte[]]$nop=@(0x90)
        if($Fault -ne 'BodyRowMissing'){Add-ListingRow $rows $at $nop $(if($Fault -eq 'BodyRowUnknown'){'<unknown>'}else{'nop'})}
        if($Fault -eq 'BodyRowDuplicate'){Add-ListingRow $rows $at $nop 'nop'}
        if($Fault -eq 'BodyRowListing'){Add-ListingRow $rows $at ([byte[]]@(0x91)) 'nop'}
    }
    $procEnd=$script:ProcEnd;$procBegin=$script:ProcBegin;$dataOwner=0;$procOwner=0;$contribSize=0x30000;$symbolTableRva=$tableRva
    if($Fault -eq 'ProcedureEndEarly'){$procEnd--};if($Fault -eq 'ProcedureEndLate'){$procEnd++};if($Fault -eq 'ProcedureBeginLate'){$procBegin++}
    if($Fault -eq 'ProcedureBeginAfterPrefix'){$procBegin=$script:Dispatch}
    if($Fault -eq 'DataStartEarly'){$symbolTableRva--};if($Fault -eq 'DataStartLate'){$symbolTableRva++}
    if($Fault -eq 'WrongProcedureOwner'){$procOwner=1};if($Fault -eq 'WrongDataOwner'){$dataOwner=1};if($Fault -eq 'ContributionShort'){$contribSize=$tableRva-$script:SectionRva}
    if($Fault -eq 'MissingDataSymbol'){$symbolData=''}else{$symbolData="  Mod $dataOwner | ``$(if($dataOwner -eq 0){'ApplicationAdjustmentClosureJobs.obj'}else{'Other.obj'})``:`n  0 | S_LDATA32 [size = 16] ```` `n  type = <no type>, addr = 0001:$($symbolTableRva-$script:SectionRva)`n"}
    if($Fault -eq 'LaterAnonymousAfterPadding'){$symbolData += "  Mod 0 | ``ApplicationAdjustmentClosureJobs.obj``:`n  0 | S_LDATA32 [size = 16] ```` `n  type = <no type>, addr = 0001:$($script:ProcEnd-$script:SectionRva+16)`n"}
    $meta="  Age: $script:Age`n  GUID: {$script:Guid}`n  Mod 0 | ``ApplicationAdjustmentClosureJobs.obj``:`n  Obj: ``ApplicationAdjustmentClosureJobs.obj```n  Mod 1 | ``Other.obj``:`n  Obj: ``Other.obj```n`nSection Contributions`n  SC[.text] | mod = 0, 0001:0, size = $contribSize, data crc = 0, reloc crc = 0`n"
    if($Fault -eq 'ContributionWrongOwner'){$meta=$meta.Replace('mod = 0, 0001:0','mod = 1, 0001:0')}
    $symbols="  Mod $procOwner | ``$(if($procOwner -eq 0){'ApplicationAdjustmentClosureJobs.obj'}else{'Other.obj'})``:`n  0 | S_GPROC32 [size = 16] ``Application::RunAdjustmentClosureSelfTest`` `n  addr = 0001:$($procBegin-$script:SectionRva), code size = $($procEnd-$procBegin)`n$symbolData"
    Set-Content (Join-Path $dir 'contributions.txt') $meta -Encoding utf8
    Set-Content (Join-Path $dir 'symbols.txt') $symbols -Encoding utf8
    Set-Content (Join-Path $dir 'disassembly.txt') (@($rows | Sort-Object {[UInt64]::Parse(($_ -split ':',2)[0],[Globalization.NumberStyles]::HexNumber)}) -join "`n") -Encoding utf8
    [IO.File]::WriteAllBytes((Join-Path $dir 'SyntheticIsa.exe'),$pe)
    $vectors=0;$evex=0
    foreach($line in $rows){if($line -match ': c5 [0-9a-f]{2} [0-9a-f]{2} [0-9a-f]{2} '){$vectors++};if($line -match ': 62 [0-9a-f]{2} [0-9a-f]{2} [0-9a-f]{2} [0-9a-f]{2} [0-9a-f]{2} '){$evex++}}
    $proofPreservingFaults=@('EffectMovEbxEax','EffectMovEaxEbx','EffectMovRdxRbx','EffectPushRbx','EffectMovBl','EffectMovBx','ProducerAlternateDisp8','ProcedureBeginLate','EntryIntoProducer','PreGuardEntryCmp','PreGuardEntryCmpFromLaterBody','DefaultTargetIsCase0','AlternateJaDefault','TargetNonVex4')
    $proofExpected=$Fault -in @('','LaterAnonymousAfterPadding','KnownIndirectCallAllowed','RealBodyVex','RealAdjacentEvex') -or $Fault -in $proofPreservingFaults
    $expectedVectors=if($Fault -eq 'RealBodyVex'){1}elseif($Fault -eq 'RealAdjacentEvex'){1}elseif($Fault -in @('TargetMidInstruction4','WrongTableTarget4')){5}elseif($proofExpected){0}else{6}
    $expectedViolations=if($Fault -in @('RealBodyVex','RealAdjacentEvex')){1}elseif($proofExpected){0}elseif($Fault -in @('TargetMidInstruction4','WrongTableTarget4')){5}else{6}
    $expectedInline=if($Fault -eq 'TargetNonVex4'){5}elseif($proofExpected){6}else{0}
    [pscustomobject]@{Name=$Name;Fault=$Fault;Binary=(Join-Path $dir 'SyntheticIsa.exe');Metadata=(Join-Path $dir 'contributions.txt');Symbols=(Join-Path $dir 'symbols.txt');Listing=(Join-Path $dir 'disassembly.txt');TableRva=$tableRva;RvaTargets=$targetList;ProducerBytes=$producer;EffectBytes=$effectBytes;VectorRows=$vectors;EvexRows=$evex;ExpectedInline=$expectedInline;ExpectedVectors=$expectedVectors;ExpectedEvex=$evex;ExpectedViolations=$expectedViolations}
}
function Assert-IndependentFixture($case){
    if(-not (Test-Path -LiteralPath $case.Binary) -or -not (Test-Path -LiteralPath $case.Metadata) -or -not (Test-Path -LiteralPath $case.Symbols) -or -not (Test-Path -LiteralPath $case.Listing)){throw "$($case.Name): fixture artifact missing"}
    [byte[]]$b=[IO.File]::ReadAllBytes($case.Binary);if($b[0] -ne 0x4d -or $b[1] -ne 0x5a){throw "$($case.Name): invalid synthetic PE signature"}
    [byte[]]$expectedProducer=switch($case.Fault){
        'ProducerMissing' { @(0x90,0x90); break }
        'ProducerAlternateDisp8' { @(0x48,0x63,0x5d,0xa8); break }
        'ProducerWrongDestination' { @(0x48,0x63,0x55,0xa0); break }
        {$_ -in @('Producer64BitWrite','ProducerUnknown')} { @(0x48,0x89,0xdb); break }
        default { @(0x48,0x63,0x5d,0xa0) }
    }
    [byte[]]$producerBytes=$b[(Raw $script:RbxProducerRva)..(Raw ($script:RbxProducerRva+$expectedProducer.Length-1))]
    if((Hex $producerBytes) -ne (Hex $expectedProducer) -or (Hex $case.ProducerBytes) -ne (Hex $expectedProducer)){throw "$($case.Name): RBX producer bytes differ from the independent literal oracle."}
    if($case.EffectBytes.Length -gt 0){
        [byte[]]$expectedEffect=switch($case.Fault){
            'EffectMovRbxImm64' { @(0x48,0xbb,0,0,0,0,0,0,0,0x80); break }
            'EffectMovRbxRax' { @(0x48,0x89,0xc3); break }
            'EffectLeaRbx' { @(0x48,0x8d,0x18); break }
            'EffectAddRbx' { @(0x48,0x83,0xc3,0x01); break }
            'EffectPopRbx' { @(0x5b); break }
            'EffectXchgRbx' { @(0x48,0x93); break }
            'EffectMovCrToRbx' { @(0x0f,0x20,0xdb); break }
            'EffectXop8F' { @(0x8f,0xe8,0x78,0xc0,0xc1); break }
            'EffectC7Group1' { @(0x48,0xc7,0xc8,0x01,0,0,0); break }
            'EffectVirtualMonitorCall' { @(0x0f,0x01,0xc1); break }
            'EffectInterrupt' { @(0xcd,0x2e); break }
            'EffectMovEbxEax' { @(0x89,0xc3); break }
            'EffectMovEaxEbx' { @(0x89,0xd8); break }
            'EffectMovRdxRbx' { @(0x48,0x89,0xda); break }
            'EffectPushRbx' { @(0x53); break }
            'EffectMovBl' { @(0xb3,0x01); break }
            'EffectMovBx' { @(0x66,0xbb,0x01,0x00); break }
            'ProducerSingle64Clobber' { @(0x48,0x89,0xdb); break }
        }
        [byte[]]$actualEffect=$b[(Raw ($script:RbxProducerRva+8))..(Raw ($script:RbxProducerRva+7+$expectedEffect.Length))]
        if((Hex $actualEffect) -ne (Hex $expectedEffect) -or (Hex $case.EffectBytes) -ne (Hex $expectedEffect)){throw "$($case.Name): post-producer effect bytes differ from independent literal oracle."}
    }
    $listing=Get-Content -Raw -LiteralPath $case.Listing
    [byte[]]$peBytes=[IO.File]::ReadAllBytes($case.Binary)
    [UInt32[]]$expectedTargets=@(0x002afbc5,0x002afcc5,0x002afdc5,0x002afec5,0x002affc5,0x002b00c5)
    switch($case.Fault){
        'AlternateJaDefault' { $expectedJaTarget=[UInt32]0x002affc4; break }
        'JaTargetIntoLoad' { $expectedJaTarget=[UInt32]0x002afbb9; break }
        'DefaultTargetIsCase0' { $expectedJaTarget=[UInt32]0x002afbc5; break }
        default { $expectedJaTarget=[UInt32]0x002affc5; break }
    }
    if($case.Fault -in @('AlternateJaDefault','JaTargetIntoLoad','DefaultTargetIsCase0','')){
        $jaAt=Raw 0x002afbac
        $actualJaTarget=[Int64]0x002afbb2+[BitConverter]::ToInt32($peBytes,$jaAt+2)
        if($actualJaTarget -ne $expectedJaTarget){throw "$($case.Name): encoded JA target does not match its independent semantic oracle."}
        if($case.Fault -eq 'AlternateJaDefault' -and -not $listing.Contains('1402affc4: 90 nop')){throw "$($case.Name): alternate JA default must target a known NOP boundary."}
    }
    if($case.Fault -in @('DirectBypassIndex','PreGuardEntryCmpFromLaterBody')){
        $branchAt=Raw 0x002afba0
        if($peBytes[$branchAt] -ne 0xe9){throw "$($case.Name): expected an encoded rel32 JMP at 0x002afba0."}
        $branchTarget=[Int64]0x002afba5+[BitConverter]::ToInt32($peBytes,$branchAt+1)
        $expectedBranchTarget=if($case.Fault -eq 'DirectBypassIndex'){[Int64]0x002afbb2}else{[Int64]0x002afba9}
        if($branchTarget -ne $expectedBranchTarget){throw "$($case.Name): encoded branch target differs from the independent safe-entry/index-bypass oracle."}
    }
    switch($case.Fault){
        'TargetNonVex4' {$expectedTargets[4]=0x002afcc3;break}
        'TargetMidInstruction4' {$expectedTargets[4]=0x002affc6;break}
        'WrongTableTarget4' {$expectedTargets[4]=0x002b13b1;break}
    }
    if($case.RvaTargets.Count -ne 6){throw "$($case.Name): oracle expected six RVA data rows."}
    for($i=0;$i -lt 6;$i++){$at=Raw ([UInt32]($case.TableRva+4*$i));$actual=[BitConverter]::ToUInt32($peBytes,$at);if($actual -ne $expectedTargets[$i] -or $case.RvaTargets[$i] -ne $expectedTargets[$i]){throw "$($case.Name): table row $i differs from its independent RVA literal."}}
    foreach($target in $expectedTargets){if($target -lt 0x002afbc5 -or $target -ge 0x002b13b2){throw ('{0}: RVA target {1:x} is outside the required [afterJump, terminalCall) interval.' -f $case.Name,$target)}}
    if($case.Fault -notin @('MissingCall','WrongCall')){
        $callAt=Raw 0x002b13b2
        if($peBytes[$callAt] -ne 0xe8){throw "$($case.Name): expected a direct CALL terminal row."}
        $callTarget=[Int64]0x002b13b7+[BitConverter]::ToInt32($peBytes,$callAt+1)
        $targetIsLocal=$callTarget -ge $script:ProcBegin -and $callTarget -lt $script:ProcEnd
        if(($case.Fault -eq 'LocalTerminalCall') -ne $targetIsLocal){throw "$($case.Name): terminal CALL locality differs from its independent semantic oracle."}
        if($case.Fault -ne 'LocalTerminalCall'){
            $externalCallAddress=$script:ImageBase+[UInt64]$callTarget
            $externalCallRow='{0:x}: c3 ret external-call-target' -f $externalCallAddress
            if($peBytes[(Raw ([UInt32]$callTarget))] -ne 0xc3 -or -not $listing.Contains($externalCallRow)){throw "$($case.Name): clean terminal CALL must target a known RET row outside the procedure."}
        }
    }
    $expectedListingVex=if($case.Fault -eq 'RealBodyVex'){7}elseif($case.Fault -in @('TargetNonVex4','TargetMidInstruction4','WrongTableTarget4')){5}else{6}
    if($case.VectorRows -ne $expectedListingVex){throw "$($case.Name): listing has $($case.VectorRows) VEX rows; independent literal listing oracle expects $expectedListingVex."}
    if($case.Fault -in @('','LaterAnonymousAfterPadding','KnownIndirectCallAllowed','EffectMovEbxEax','EffectMovEaxEbx','EffectMovRdxRbx','EffectPushRbx','EffectMovBl','EffectMovBx','ProducerAlternateDisp8','ProcedureBeginLate','EntryIntoProducer','PreGuardEntryCmp','PreGuardEntryCmpFromLaterBody','DefaultTargetIsCase0','AlternateJaDefault','RealAdjacentEvex') -and $case.VectorRows -ne 6){throw "$($case.Name): proof-preserving control must retain exactly six table VEX listing rows."}
    if($case.Fault -eq 'TargetNonVex4' -and ($case.ExpectedInline -ne 5 -or $case.ExpectedVectors -ne 0 -or $case.ExpectedViolations -ne 0)){throw 'TargetNonVex4 must retain proof for five VEX table rows and suppress all vectors.'}
    if($case.Fault -in @('','ProducerAlternateDisp8')){
        $expectedProducerRow=if($case.Fault -eq 'ProducerAlternateDisp8'){'1402afb80: 48 63 5d a8 movsxd rbx, dword ptr [rbp-0x58]'}else{'1402afb80: 48 63 5d a0 movsxd rbx, dword ptr [rbp-0x60]'}
        if(-not $listing.Contains($expectedProducerRow)){throw "$($case.Name): valid MOVSXD-to-RBX producer must be one known PE-matched listing row."}
    }
    if($case.Fault -eq 'RealBodyVex' -and $case.VectorRows -ne 7){throw 'Real body VEX control must add one real vector to the six table listing rows.'}
    if($case.Fault -eq 'RealAdjacentEvex' -and $case.EvexRows -ne 1){throw 'Adjacent EVEX control must contain exactly one EVEX row.'}
    if($listing.Length -eq 0){throw "$($case.Name): empty disassembly listing"}
    if($case.Fault -notin @('TableMidInstruction','BodyRowDuplicate','BodyRowListing','ProducerDuplicate') -and $case.Fault -notmatch 'DuplicateRow$'){
        $orderedRows=[Collections.Generic.List[object]]::new()
        foreach($line in $listing -split '\r?\n'){
            if($line -match '^([0-9a-f]+): ((?:[0-9a-f]{2}(?: [0-9a-f]{2})*)) '){
                $address=[UInt64]::Parse($Matches[1],[Globalization.NumberStyles]::HexNumber)
                $byteCount=($Matches[2] -split ' ').Count
                $orderedRows.Add([pscustomobject]@{Start=$address;End=$address+[UInt64]$byteCount;Line=$line})
            }
        }
        $orderedRows.Sort([Comparison[object]]{param($a,$b) $a.Start.CompareTo($b.Start)})
        for($i=1;$i -lt $orderedRows.Count;$i++){if($orderedRows[$i].Start -lt $orderedRows[$i-1].End){throw "$($case.Name): listing rows overlap: $($orderedRows[$i-1].Line) / $($orderedRows[$i].Line)"}}
    }
}
$cases=[Collections.Generic.List[object]]::new()
$cases.Add(@{Name='ValidSixRvaRows';Fault='';Row=-1})
foreach($i in 0..5){foreach($mode in 'Missing','Duplicate','Unknown','Listing'){$cases.Add(@{Name="Dispatch${i}${mode}";Fault="${mode}Row";Row=$i})}}
foreach($fault in @('WrongCmpOpcode','WrongCmpRegister','WrongCmpImmediate','WrongCount','WrongJaCondition','JaTargetIntoLoad','WrongLeaRegister','WrongImageBase','WrongLoadOpcode','WrongLoadDestination','WrongLoadBase','WrongLoadIndex','WrongLoadScale','WrongTableOperand','WrongAddOpcode','WrongAddRegisters','WrongJumpOpcode','WrongJumpRegister','Max0','Max128','DefaultTargetIsCase0','DefaultTargetIntoLoad','AlternateJaDefault','DirectBypassIndex','PreGuardEntryCmpFromLaterBody','OtherIndirectJump','TableAfterPadding','TableMidInstruction','MissingCall','WrongCall','LocalTerminalCall','MissingTrap','WrongTrap','ProcedureEndEarly','ProcedureEndLate','ProcedureBeginLate','ProcedureBeginAfterPrefix','WrongProcedureOwner','MissingDataSymbol','DataStartEarly','DataStartLate','WrongDataOwner','ContributionShort','ContributionWrongOwner','WrongTableTarget4','TargetMidInstruction4','TargetNonVex4','BodyRowMissing','BodyRowDuplicate','BodyRowUnknown','BodyRowListing','ProducerMissing','ProducerAlternateDisp8','ProducerWrongDestination','Producer64BitWrite','ProducerUnknown','ProducerDuplicate','ProducerListing','ProducerCrossingEntry','ProducerSingle64Clobber','EntryBypassesProducer','EntryIntoProducer','EntryIntoJa','EntryIntoLea','EntryIntoLoad','EntryIntoAdd','EntryIntoJump','LocalCallIntoGuard','PreGuardBypassJa','PreGuardBypassLea','PreGuardBypassLoad','PreGuardBypassAdd','PreGuardBypassJump','EffectMovRbxImm64','EffectMovRbxRax','EffectLeaRbx','EffectAddRbx','EffectPopRbx','EffectXchgRbx','EffectMovCrToRbx','EffectXop8F','EffectC7Group1','EffectVirtualMonitorCall','EffectInterrupt','EffectMovEbxEax','EffectMovEaxEbx','EffectMovRdxRbx','EffectPushRbx','EffectMovBl','EffectMovBx','RealBodyVex','RealAdjacentEvex','LaterAnonymousAfterPadding','KnownIndirectCallAllowed')){$cases.Add(@{Name=$fault;Fault=$fault;Row=-1})}
$cases.Add(@{Name='PreGuardEntryCmp';Fault='PreGuardEntryCmp';Row=-1})
if ($cases.Count -ne 120 -or @($cases | ForEach-Object { $_.Name } | Select-Object -Unique).Count -ne 120) {
    throw 'The direct RBX scanner roster must contain 120 distinct controls.'
}
$script:FixtureRoot = Join-Path $repo ('.build/BuildProcessTests/IsaRbxDirectGuard-' + [guid]::NewGuid().ToString('N'))
[void](New-Item -ItemType Directory -Path $script:FixtureRoot -Force)
$scanFailures = [Collections.Generic.List[string]]::new()
$passed = 0
foreach ($spec in $cases) {
    $created = @(New-Control $spec.Name $spec.Fault $spec.Row)
    $case = $created[$created.Count - 1]
    Assert-IndependentFixture $case
    try {
        $scan = [RedPrismBuild.IsaScanner]::Scan($case.Binary, $case.Metadata, $case.Symbols, $case.Listing,
                                               [string[]]@(), [string[]]@(), [string[]]@())
        $actual = "$($scan.InlineTableVectorData)/$($scan.VectorInstructions)/$($scan.EvexInstructions)/$($scan.Violations.Count)"
        $expected = "$($case.ExpectedInline)/$($case.ExpectedVectors)/$($case.ExpectedEvex)/$($case.ExpectedViolations)"
        if ($actual -ne $expected) {
            $scanFailures.Add("$($case.Name): inline/vector/EVEX/violations $actual, expected $expected")
        } else {
            Write-Host "PASS isa-rbx-direct-guard.$($case.Name)"
            ++$passed
        }
    } catch {
        $scanFailures.Add("$($case.Name): scanner threw $($_.Exception.GetType().Name): $($_.Exception.Message)")
    }
}
Write-Host "IsaRbxDirectGuard controls: $($cases.Count), passed=$passed, failures=$($scanFailures.Count)."
if ($scanFailures.Count -ne 0 -or $passed -ne 120) {
    throw ($scanFailures -join "`n")
}
